<?php declare(strict_types=1);namespace StudPulse\Integrations;final class Calendar{private static function escape(string$s):string{return str_replace(["\\","\r","\n",';',','],["\\\\",'',"\\n",'\\;','\\,'],$s);}private static function fold(string$line):string{$out='';while(strlen($line)>73){$part=mb_strcut($line,0,73,'UTF-8');$out.=$part."\r\n ";$line=substr($line,strlen($part));}return$out.$line;}public static function export(array$meetings,array$homework=[]):string{$lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//StudPulse//Student workspace//RU','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:StudPulse','X-WR-TIMEZONE:Europe/Moscow','BEGIN:VTIMEZONE','TZID:Europe/Moscow','BEGIN:STANDARD','DTSTART:20141026T020000','TZOFFSETFROM:+0400','TZOFFSETTO:+0300','TZNAME:MSK','END:STANDARD','END:VTIMEZONE'];foreach($meetings as$m){$tz=new \DateTimeZone('Europe/Moscow');$start=(new \DateTimeImmutable($m['start_at'],new \DateTimeZone('UTC')))->setTimezone($tz);$end=(new \DateTimeImmutable($m['end_at'],new \DateTimeZone('UTC')))->setTimezone($tz);array_push($lines,'BEGIN:VEVENT','UID:meeting-'.$m['id'].'@studpulse.ru','DTSTAMP:'.gmdate('Ymd\THis\Z',strtotime($m['last_synced_at'].' UTC')),'DTSTART;TZID=Europe/Moscow:'.$start->format('Ymd\THis'),'DTEND;TZID=Europe/Moscow:'.$end->format('Ymd\THis'),'SUMMARY:'.self::escape(($m['source']==='fixture'?'[ДЕМО] ':'').$m['subject_title']),'LOCATION:'.self::escape($m['official_room_code']??''),'SEQUENCE:'.(int)$m['revision'],'STATUS:'.($m['status']==='cancelled'?'CANCELLED':'CONFIRMED'),'END:VEVENT');}foreach($homework as$h){if(!$h['due_at']){continue;}$stamp=gmdate('Ymd\THis\Z',strtotime($h['updated_at'].' UTC'));array_push($lines,'BEGIN:VTODO','UID:homework-'.$h['id'].'@studpulse.ru','DTSTAMP:'.$stamp,'DUE:'.gmdate('Ymd\THis\Z',strtotime($h['due_at'].' UTC')),'SUMMARY:'.self::escape($h['title']),'SEQUENCE:'.(int)$h['revision'],'END:VTODO');}$lines[]='END:VCALENDAR';return implode("\r\n",array_map(self::fold(...),$lines))."\r\n";}}